<?php if(empty($question)): ?><section class="empty-state"><span class="empty-icon">?</span><h1>Question not found</h1><p>This question may have been deleted or the link may be incorrect.</p><a class="button button-primary" href="<?= e(url()) ?>">Back to the feed</a></section><?php else: $editing=(isset($_GET['edit']) && current_user() && (int)current_user()['id']===(int)$question['user_id']); ?><div class="detail-layout"><article class="detail-main"><a class="back-link" href="<?= e(url()) ?>">← Back to questions</a><?php if($editing): ?><section class="form-page inline-edit"><p class="eyebrow">YOUR QUESTION</p><h1>Edit question</h1><form class="surface-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="question_update"><input type="hidden" name="id" value="<?= (int)$question['id'] ?>"><label>Question title</label><input name="title" maxlength="180" minlength="12" required value="<?= e($question['title']) ?>"><label>Details</label><textarea name="body" rows="9" minlength="20" required><?= e($question['body']) ?></textarea><label>Topic</label><select name="category_id" required><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$c['id']===(int)$question['category_id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><label>Tags</label><input name="tags" value="<?= e(implode(', ',array_column($tags,'name'))) ?>"><div class="form-actions"><a class="text-link" href="<?= e(url('question',['id'=>$question['id']])) ?>">Cancel</a><button class="button button-primary">Save changes</button></div></form></section><?php else: ?>
<article class="question-detail"><div class="detail-meta"><a class="category-pill" href="<?= e(url('category',['slug'=>$question['category_slug']])) ?>"><?= e($question['category_name']) ?></a><span><?= e(nice_date($question['created_at'])) ?></span><?php if($question['updated_at']!==$question['created_at']): ?><span>· Edited <?= e(nice_date($question['updated_at'])) ?></span><?php endif; ?></div><h1><?= e($question['title']) ?></h1><div class="detail-author"><a class="author-mini" href="<?= e(url('profile',['username'=>$question['username']])) ?>"><span class="avatar"><?= e(initials($question['full_name'])) ?></span><span><b><?= e($question['full_name']) ?></b><small>@<?= e($question['username']) ?> · <?= reputation_for((int)$question['user_id']) ?> reputation</small></span></a><?php if(current_user() && (int)current_user()['id']===(int)$question['user_id']): ?><div class="owner-actions"><a class="text-link" href="<?= e(url('question',['id'=>$question['id'],'edit'=>1])) ?>">Edit</a><form method="post" data-confirm="Delete this question and all its answers?"><?= csrf_field() ?><input type="hidden" name="action" value="question_delete"><input type="hidden" name="id" value="<?= (int)$question['id'] ?>"><button class="text-link danger-link">Delete</button></form></div><?php endif; ?></div><div class="detail-body"><?= nl2br(e($question['body'])) ?></div><?php if($tags): ?><div class="tag-row detail-tags"><?php foreach($tags as $tag): ?><span class="tag">#<?= e($tag['name']) ?></span><?php endforeach; ?></div><?php endif; ?><div class="detail-actions"><div class="vote-inline"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="vote"><input type="hidden" name="kind" value="question"><input type="hidden" name="id" value="<?= (int)$question['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="vote-button <?= (int)$question['my_vote']===1?'voted':'' ?>" name="value" value="1" aria-label="Upvote question">↑</button></form><b><?= (int)$question['vote_score'] ?> votes</b><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="vote"><input type="hidden" name="kind" value="question"><input type="hidden" name="id" value="<?= (int)$question['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="vote-button down <?= (int)$question['my_vote']===-1?'voted':'' ?>" name="value" value="-1" aria-label="Downvote question">↓</button></form></div><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="bookmark"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="save-button <?= $isBookmarked?'saved':'' ?>"><?= $isBookmarked?'◆ Saved':'◇ Save question' ?></button></form><?php else: ?><a class="save-button" href="<?= e(url('login')) ?>">◇ Save question</a><?php endif; ?></div></article>
