<input type="hidden" name="kind" value="answer"><input type="hidden" name="id" value="<?= (int)$answer['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="vote-button <?= (int)$answer['my_vote']===1?'voted':'' ?>" name="value" value="1" aria-label="Upvote answer">↑</button></form><b><?= (int)$answer['vote_score'] ?></b><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="vote"><input type="hidden" name="kind" value="answer"><input type="hidden" name="id" value="<?= (int)$answer['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><button class="vote-button down <?= (int)$answer['my_vote']===-1?'voted':'' ?>" name="value" value="-1" aria-label="Downvote answer">↓</button></form></div><a class="author-mini" href="<?= e(url('profile',['username'=>$answer['username']])) ?>"><span class="avatar avatar-sm"><?= e(initials($answer['full_name'])) ?></span><span><?= e($answer['full_name']) ?></span><small><?= reputation_for((int)$answer['user_id']) ?> rep</small></a><?php if(current_user()&&(int)current_user()['id']===(int)$question['user_id']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="accept_answer"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><input type="hidden" name="answer_id" value="<?= (int)$answer['id'] ?>"><button class="accept-button"><?= (int)$question['accepted_answer_id']===(int)$answer['id']?'Remove accepted':'✓ Accept answer' ?></button></form><?php endif; ?></div></article><?php endforeach; else: ?><div class="empty-answer"><span>✦</span><h3>No answers yet</h3><p>Share a helpful explanation and be the first to answer.</p></div><?php endif; ?></section>
<section class="answer-composer"><p class="eyebrow">ADD TO THE CONVERSATION</p><h2>Your answer</h2><?php if(current_user()): ?><form method="post" class="surface-form"><?= csrf_field() ?><input type="hidden" name="action" value="answer_create"><input type="hidden" name="question_id" value="<?= (int)$question['id'] ?>"><textarea name="body" rows="7" minlength="10" maxlength="12000" required placeholder="Share your explanation, experience, or a useful resource…"></textarea><div class="form-actions"><small>Be kind, clear, and constructive.</small><button class="button button-primary">Post answer <span>↗</span></button></div></form><?php else: ?><div class="sign-in-prompt"><p>Have an idea to share? Sign in to join the conversation.</p><a class="button button-primary" href="<?= e(url('login')) ?>">Sign in to answer</a><a class="text-link" href="<?= e(url('register')) ?>">Create an account</a></div><?php endif; ?></section><?php endif; ?></article>
<aside class="detail-sidebar"><div class="side-card question-stats"><p class="eyebrow">AT A GLANCE</p><div><strong><?= (int)$question['vote_score'] ?></strong><span>community votes</span></div><div><strong><?= count($answers) ?></strong><span><?= count($answers)===1?'answer':'answers' ?></span></div><div><strong><?= e(nice_date($question['created_at'])) ?></strong><span>asked</span></div><?php if($question['accepted_answer_id']): ?><div class="stat-accepted">✓ An answer was accepted</div><?php endif; ?></div><div class="side-card"><p class="eyebrow">KEEP EXPLORING</p><h3>Questions grow the community.</h3><p>Have a different question? Share it with students who are learning alongside you.</p><a class="button button-outline full-width" href="<?= e(url('ask')) ?>">＋ Ask a question</a></div></aside></div><?php endif; ?>
